function findMaximumLength(nums) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  const dp = new Array(n + 1).fill(0);
  const need = new Array(n + 1).fill(0);
  const queue = [0];
  let head = 0;
  for (let i = 1; i <= n; i++) {
    while (head + 1 < queue.length && need[queue[head + 1]] <= prefix[i]) {
      head++;
    }
    const j = queue[head];
    dp[i] = dp[j] + 1;
    need[i] = 2 * prefix[i] - prefix[j];
    while (queue.length > head && need[queue[queue.length - 1]] >= need[i]) {
      queue.pop();
    }
    queue.push(i);
  }
  return dp[n];
}

