function findMaximumLength(nums) {
  const n = nums.length;
  let best = 0;
  // Each bit of mask says whether a cut is placed after that position.
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    const sums = [];
    let current = 0;
    for (let k = 0; k < n; k++) {
      current += nums[k];
      if (k === n - 1 || (mask >> k) & 1) {
        sums.push(current);
        current = 0;
      }
    }
    let ok = true;
    for (let k = 1; k < sums.length; k++) if (sums[k] < sums[k - 1]) ok = false;
    if (ok && sums.length > best) best = sums.length;
  }
  return best;
}

