function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const top = [3, 10, 30][Math.floor(rand() * 3)];
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
  }
  const n = 2000;
  rand(); // The first draw follows the seed closely, so skip it before choosing a shape.
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 100000))];
  if (mode === 1) return [Array.from({ length: n }, (_, k) => Math.max(1, 100000 - k * 50 - Math.floor(rand() * 40)))];
  return [Array.from({ length: n }, () => (rand() < 0.1 ? 50000 + Math.floor(rand() * 50001) : 1 + Math.floor(rand() * 100)))];
}
